function getSopForDay(day) {
  const boundedDay = Math.max(1, Math.min(46, Math.round(day)));
  const item = BROILER_SOP_SCHEDULE.find((s2) => s2.day === boundedDay);
  if (item) return item;
  return BROILER_SOP_SCHEDULE[BROILER_SOP_SCHEDULE.length - 1];
}
