function getSonaliSopForDay(day) {
  const bounded = Math.max(1, Math.min(60, Math.round(day)));
  const found = SONALI_SOP_SCHEDULE.find((s2) => s2.day === bounded);
  if (found) return found;
  return SONALI_SOP_SCHEDULE[SONALI_SOP_SCHEDULE.length - 1];
}
